const state={model:null,context:null,reservoir:null,rate:1.2,duration:20,year:12,percentile:50,layer:"pressure",limit:25,selectedIndex:null,basemap:true,showWells:true,showFaults:true,betaEnabled:false,faultState:"semi-open",view:{lon:9.95,lat:56.62,zoom:9}};
const $=id=>document.getElementById(id);
const els={reservoir:$('reservoirSelect'),rate:$('rateInput'),duration:$('durationInput'),year:$('yearInput'),limit:$('limitInput'),map:$('pressureMap'),chart:$('pressureChart'),tooltip:$('mapTooltip')};
const palettes={pressure:['#263344','#657ca5','#c27355','#f0ce6b'],margin:['#d05f55','#d5a85d','#9aaa75','#5d9f99'],geothermal:['#273945','#47777e','#62aaa7','#b8ddd0'],co2:['#202936','#315b6e','#62aaa7','#d7cf7a'],depth:['#d9cba1','#a98b68','#775b4d','#493d43'],thickness:['#2b3440','#5b7188','#8fb2ae','#e0cf8a'],permeability:['#312e43','#5b5688','#9a87b8','#e1c58e'],porosity:['#283942','#47777e','#70aaa4','#c7d8a2']};
const TILE_SIZE=256,MAP_W=900,MAP_H=650,MIN_ZOOM=6,MAX_ZOOM=13;
let mapDrag=null,mapMoved=false;

function hexRgb(hex){const v=hex.replace('#','');return[0,2,4].map(i=>parseInt(v.slice(i,i+2),16))}
function colour(palette,t){t=Math.max(0,Math.min(.999,t));const n=t*(palette.length-1),i=Math.floor(n),f=n-i,a=hexRgb(palette[i]),b=hexRgb(palette[i+1]);return`rgb(${a.map((x,j)=>Math.round(x+(b[j]-x)*f)).join(',')})`}
function fmt(value,digits=1){return Number(value).toLocaleString('en-GB',{minimumFractionDigits:digits,maximumFractionDigits:digits})}
function clampLat(lat){return Math.max(-85.05112878,Math.min(85.05112878,lat))}
function world(point,zoom=state.view.zoom){const scale=TILE_SIZE*2**zoom,sin=Math.sin(clampLat(point.lat)*Math.PI/180);return{x:(point.lon+180)/360*scale,y:(.5-Math.log((1+sin)/(1-sin))/(4*Math.PI))*scale}}
function unworld(x,y,zoom=state.view.zoom){const scale=TILE_SIZE*2**zoom,n=Math.PI-2*Math.PI*y/scale;return{lon:x/scale*360-180,lat:180/Math.PI*Math.atan(Math.sinh(n))}}
function mapHeight(){const r=els.map?.getBoundingClientRect();return r?.width>0&&r?.height>0?MAP_W*r.height/r.width:MAP_H}
function project(point){const p=world(point),c=world(state.view),h=mapHeight();return{x:p.x-c.x+MAP_W/2,y:p.y-c.y+h/2}}
function reservoirBounds(){const points=state.reservoir.points;return{minLon:Math.min(...points.map(p=>p.lon)),maxLon:Math.max(...points.map(p=>p.lon)),minLat:Math.min(...points.map(p=>p.lat)),maxLat:Math.max(...points.map(p=>p.lat))}}
function fitView(){const b=reservoirBounds(),h=mapHeight();let zoom=MIN_ZOOM;for(let z=MAX_ZOOM;z>=MIN_ZOOM;z--){const nw=world({lon:b.minLon,lat:b.maxLat},z),se=world({lon:b.maxLon,lat:b.minLat},z);if(se.x-nw.x<=MAP_W-90&&se.y-nw.y<=h-90){zoom=z;break}}const nw=world({lon:b.minLon,lat:b.maxLat},zoom),se=world({lon:b.maxLon,lat:b.minLat},zoom);state.view={...unworld((nw.x+se.x)/2,(nw.y+se.y)/2,zoom),zoom}}
function zoomMap(delta,anchor){const h=mapHeight(),focus=anchor||{x:MAP_W/2,y:h/2},next=Math.max(MIN_ZOOM,Math.min(MAX_ZOOM,state.view.zoom+delta));if(next===state.view.zoom)return;const c=world(state.view),under=unworld(c.x-MAP_W/2+focus.x,c.y-h/2+focus.y),p=world(under,next),nextCentre=unworld(p.x-focus.x+MAP_W/2,p.y-focus.y+h/2,next);state.view={...nextCentre,zoom:next};renderMap()}
function nearestTimeIndex(year){const ts=state.model.times_years;let best=0;ts.forEach((v,i)=>{if(Math.abs(v-year)<Math.abs(ts[best]-year))best=i});return best}
function scenarioKey(beta=state.betaEnabled){return`${state.faultState}_${beta?'alpha_beta':'alpha'}`}
function scenarioValue(point,field,year=state.year){const ti=nearestTimeIndex(Math.min(year,state.duration)),pi={10:0,50:1,90:2}[state.percentile],scenarios=point[field];if(!scenarios)return null;const single=scenarios[scenarioKey(false)]?.[ti]?.[pi]??0,dual=scenarios[scenarioKey(true)]?.[ti]?.[pi]??single;return single*state.rate+(state.betaEnabled?dual-single:0)}
function pressureAt(point,year=state.year){const ti=nearestTimeIndex(Math.min(year,state.duration)),pi={10:0,50:1,90:2}[state.percentile];let value=scenarioValue(point,'scenario_pressure_bar',year);if(value==null)value=point.pressure_bar[ti][pi]*state.rate;return year<=state.duration?value:value*Math.sqrt(state.duration/year)}
function co2At(point){let value=scenarioValue(point,'scenario_co2_saturation');if(value==null){const ti=nearestTimeIndex(Math.min(state.year,state.duration)),pi={10:0,50:1,90:2}[state.percentile];value=point.co2_saturation?.[ti]?.[pi]??0}return Math.max(0,Math.min(100,value))}
function propertyValue(point){if(state.layer==='depth')return point.depth_m;if(state.layer==='thickness')return point.thickness_m;if(state.layer==='permeability')return point.permeability_md;if(state.layer==='porosity')return point.porosity*100;return null}
function valueAt(point){const property=propertyValue(point);if(property!=null)return property;const pressure=pressureAt(point),margin=Math.max(0,state.limit-pressure);if(state.layer==='pressure')return pressure;if(state.layer==='margin')return margin;if(state.layer==='co2')return co2At(point);return Math.min(100,pressure/state.limit*22)}
function ranges(){if(state.layer==='pressure'||state.layer==='margin')return[0,state.limit];if(state.layer==='co2')return[0,80];if(state.layer==='geothermal')return[0,25];const values=state.reservoir.points.map(propertyValue).filter(v=>Number.isFinite(v)).sort((a,b)=>a-b);return[values[Math.floor(values.length*.02)]??0,values[Math.floor(values.length*.98)]??1]}

function populateReservoirs(){els.reservoir.innerHTML=state.model.reservoirs.filter(r=>r.assessment_type==='deep_geothermal').map(r=>`<option value="${r.id}">${r.name}</option>`).join('');els.reservoir.value='gassum';selectReservoir('gassum')}
function depthScreen(){return state.context.co2_depth_screen.find(item=>item.id===state.reservoir.id)}
function selectReservoir(id){state.reservoir=state.model.reservoirs.find(r=>r.id===id)||state.model.reservoirs[0];fitView();const points=state.reservoir.points,b=reservoirBounds(),target={lon:b.minLon+(b.maxLon-b.minLon)*.7,lat:b.minLat+(b.maxLat-b.minLat)*.58};state.selectedIndex=points.reduce((best,p,i)=>((p.lon-target.lon)**2+(p.lat-target.lat)**2)<((points[best].lon-target.lon)**2+(points[best].lat-target.lat)**2)?i:best,0);const screen=depthScreen(),borderline=screen.minimum_depth_m<900;$('reservoirSubtitle').textContent=`${state.reservoir.name} · regional screening grid`;$('depthScreen').className=`depth-screen ${borderline?'warning':'eligible'}`;$('depthScreen').textContent=`CO₂ depth screen: ${fmt(screen.minimum_depth_m,0)}–${fmt(screen.maximum_depth_m,0)} m${borderline?' · borderline shallow cells':' · ≥800 m'}`;$('engineLabel').textContent=state.reservoir.is_opm_result?`OPM Flow 2026.04 · ${state.reservoir.ensemble_size} realizations × 6 scenarios`:`${state.reservoir.ensemble_size}-member analytical proxy`;$('provenance').textContent=`${state.model.model_version} · ${state.reservoir.is_opm_result?'OPM CO2STORE':'proxy'}`;$('faultState').disabled=!state.reservoir.fault_scenarios;$('betaToggle').disabled=!state.reservoir.storage_projects;render()}

function osmTiles(){if(!state.basemap)return'';const h=mapHeight(),z=state.view.zoom,n=2**z,c=world(state.view),topLeft={x:c.x-MAP_W/2,y:c.y-h/2},minX=Math.floor(topLeft.x/TILE_SIZE),maxX=Math.floor((topLeft.x+MAP_W)/TILE_SIZE),minY=Math.floor(topLeft.y/TILE_SIZE),maxY=Math.floor((topLeft.y+h)/TILE_SIZE);let out='<g class="osm-tiles">';for(let y=minY;y<=maxY;y++)for(let x=minX;x<=maxX;x++){if(y>=0&&y<n)out+=`<image href="https://tile.openstreetmap.org/${z}/${((x%n)+n)%n}/${y}.png" x="${x*TILE_SIZE-topLeft.x}" y="${y*TILE_SIZE-topLeft.y}" width="256" height="256"/>`}return out+'</g>'}
function cellSize(){const points=state.reservoir.points;if(points.length<2)return{w:10,h:10};const row=points.findIndex((p,i)=>i>0&&p.lon<points[i-1].lon),a=project(points[0]),b=project(points[1]),c=project(points[row>0?row:1]);return{w:Math.max(3,Math.min(30,Math.hypot(b.x-a.x,b.y-a.y)+1)),h:Math.max(3,Math.min(30,Math.hypot(c.x-a.x,c.y-a.y)+1))}}
function pathFor(points){return points.map((p,i)=>{const s=project({lon:p[0],lat:p[1]});return`${i?'L':'M'}${s.x.toFixed(1)} ${s.y.toFixed(1)}`}).join('')}
function renderFaults(){if(!state.showFaults)return'';return`<g class="faults">${state.context.faults.map(f=>`<path class="fault-trace ${f.id==='polygon_23'?`modelled ${state.faultState}`:''}" d="${pathFor(f.points)}"><title>${f.name}${f.id==='polygon_23'?` · modelled ${state.faultState}`:''}</title></path>`).join('')}</g>`}
function renderWells(){if(!state.showWells)return'';return`<g class="legacy-wells">${state.context.legacy_wells.map(w=>{const p=project(w);return`<g class="legacy-well" transform="translate(${p.x.toFixed(1)} ${p.y.toFixed(1)})"><circle r="6"/><path d="M-4-4L4 4M4-4L-4 4"/><text x="9" y="-7">${w.name}</text><title>${w.name} · ${w.status} · potential leakage pathway screen</title></g>`}).join('')}</g>`}
function renderProjects(){const projects=state.reservoir.storage_projects||[{id:'alpha',name:'Storage Alpha',...state.reservoir.reference_injector}];return projects.map(item=>{const p=project(item),enabled=item.id!=='beta'||state.betaEnabled,rate=item.id==='alpha'?state.rate:1;return`<g class="project-marker storage ${enabled?'':'inactive'}" transform="translate(${p.x} ${p.y})"><circle r="10"/><path d="M0-17V12M-6-8H6"/><text x="15" y="-8">${item.name}</text><text x="15" y="8">${enabled?`${rate.toFixed(1)} Mt/yr`:'OFF'}</text></g>`}).join('')}
function renderMap(){const h=mapHeight(),points=state.reservoir.points,[lo,hi]=ranges(),palette=palettes[state.layer],size=cellSize();els.map.setAttribute('viewBox',`0 0 ${MAP_W} ${h}`);let svg=`<defs><pattern id="minorGrid" width="36" height="36" patternUnits="userSpaceOnUse"><path d="M36 0H0V36" fill="none" stroke="#526171" stroke-opacity=".12"/></pattern></defs><rect width="${MAP_W}" height="${h}" fill="#171d25"/>${osmTiles()}<rect width="${MAP_W}" height="${h}" fill="url(#minorGrid)"/>`;points.forEach((p,i)=>{const s=project(p),v=valueAt(p),t=(v-lo)/Math.max(hi-lo,.001),selected=i===state.selectedIndex,opacity=state.basemap ? .68 : .86;svg+=`<rect class="model-cell" data-index="${i}" x="${(s.x-size.w/2).toFixed(1)}" y="${(s.y-size.h/2).toFixed(1)}" width="${size.w.toFixed(1)}" height="${size.h.toFixed(1)}" rx="1" fill="${colour(palette,t)}" opacity="${opacity}"/>`;if(selected)svg+=`<circle class="selected-ring" cx="${s.x.toFixed(1)}" cy="${s.y.toFixed(1)}" r="10"/>`});svg+=renderFaults()+renderWells()+renderProjects();const b=reservoirBounds(),geoA=project({lon:b.minLon+(b.maxLon-b.minLon)*.7,lat:b.minLat+(b.maxLat-b.minLat)*.58}),geoB=project({lon:b.minLon+(b.maxLon-b.minLon)*.34,lat:b.minLat+(b.maxLat-b.minLat)*.3});svg+=`<g class="project-marker geothermal" transform="translate(${geoA.x} ${geoA.y})"><circle r="9"/><path d="M-4 4L0-6 4 4M-3 1H3"/><text x="14" y="4">GeoHeat North</text></g><g class="project-marker geothermal" transform="translate(${geoB.x} ${geoB.y})"><circle r="9"/><path d="M-4 4L0-6 4 4M-3 1H3"/><text x="14" y="4">GeoHeat South</text></g>`;els.map.innerHTML=svg;$('osmAttribution').hidden=!state.basemap;$('zoomReadout').textContent=`z${state.view.zoom}`;els.map.querySelectorAll('.model-cell').forEach(cell=>{cell.addEventListener('pointerenter',e=>showTooltip(e,Number(cell.dataset.index)));cell.addEventListener('pointerleave',()=>els.tooltip.hidden=true)})}
function showTooltip(event,index){const p=state.reservoir.points[index],v=pressureAt(p),headline=state.layer==='co2'?`${fmt(co2At(p))}% CO₂ saturation · P${state.percentile}`:propertyValue(p)!=null?`${fmt(propertyValue(p),state.layer==='porosity'?1:0)} ${state.layer==='porosity'?'%':state.layer==='permeability'?'mD':'m'} · ${layerLabels()[1]}`:`${fmt(v)} bar Δp · P${state.percentile}`;els.tooltip.innerHTML=`<strong>${headline}</strong><span>${fmt(p.depth_m,0)} m top depth · ${fmt(p.permeability_md,0)} mD</span>`;els.tooltip.hidden=false;const canvas=document.querySelector('.map-canvas').getBoundingClientRect();els.tooltip.style.left=`${Math.min(canvas.width-205,event.clientX-canvas.left+12)}px`;els.tooltip.style.top=`${Math.max(65,event.clientY-canvas.top-12)}px`}

function renderDetail(){const p=state.reservoir.points[state.selectedIndex],pressure=pressureAt(p),margin=state.limit-pressure,use=Math.max(0,pressure/state.limit*100),maxRate=state.rate*state.limit/Math.max(pressure,.01);$('selectedName').textContent=`Cell ${state.selectedIndex+1}`;$('budgetValue').textContent=`${fmt(use,0)}%`;$('budgetBar').style.width=`${Math.min(100,use)}%`;$('budgetBar').style.background=use>100?'#d26055':use>75?'#d09e58':'#dec16b';$('budgetCaption').textContent=use>100?'Configured pressure constraint exceeded in this screening case.':`${fmt(Math.max(0,100-use),0)}% of the configured pressure headroom remains.`;$('pressureValue').textContent=`+${fmt(pressure)} bar`;$('pressureContext').textContent=`P${state.percentile} · year ${state.year}`;$('marginValue').textContent=`${margin>=0?'+':'−'}${fmt(Math.abs(margin))} bar`;$('injectionCost').textContent=`+${fmt(pressure*.78,0)}%`;$('productionCost').textContent=`−${fmt(pressure*.41,0)}%`;$('maxRate').textContent=`${fmt(Math.min(9.9,maxRate))} Mt/yr`;$('bindingConstraint').textContent=use>78?'Pressure headroom':state.betaEnabled?'Project interference':'Geothermal receptor';$('envelopeTitle').textContent=use>100?'Scenario exceeds the configured screening envelope':use>78?'Scenario approaches a binding constraint':'Scenario remains inside the screening envelope';$('envelopeText').textContent=use>78?'Reduce rate, isolate a compartment, or run a calibrated geomechanical case.':`${state.faultState} fault · ${state.betaEnabled?'two':'one'} storage project${state.betaEnabled?'s':''}; headroom remains provisional.`;renderChart(p)}
function renderChart(p){const w=320,h=165,left=34,right=10,top=12,bottom=25,years=[1,5,10,20,30,40,50,60],values=years.map(y=>pressureAt(p,y)),max=Math.max(state.limit,...values)*1.12,x=y=>left+(y/60)*(w-left-right),y=v=>top+(1-v/max)*(h-top-bottom);let svg='';[0,.5,1].forEach(f=>{const yy=top+f*(h-top-bottom),val=max*(1-f);svg+=`<line class="chart-grid" x1="${left}" y1="${yy}" x2="${w-right}" y2="${yy}"/><text class="chart-axis" x="2" y="${yy+3}">${fmt(val,0)}</text>`});svg+=`<line class="chart-limit" x1="${left}" y1="${y(state.limit)}" x2="${w-right}" y2="${y(state.limit)}"/><text class="chart-axis" x="${w-55}" y="${y(state.limit)-4}">limit</text>`;const line=years.map((yr,i)=>`${i?'L':'M'}${x(yr).toFixed(1)} ${y(values[i]).toFixed(1)}`).join('');svg+=`<path class="chart-area" d="${line}L${x(60)} ${h-bottom}L${left} ${h-bottom}Z"/><path class="chart-line" d="${line}"/>`;years.forEach((yr,i)=>svg+=`<circle class="chart-point" cx="${x(yr)}" cy="${y(values[i])}" r="3"/>`);[0,20,40,60].forEach(yr=>svg+=`<text class="chart-axis" x="${x(yr)-5}" y="${h-7}">${yr}</text>`);svg+=`<text class="chart-axis" x="${w-30}" y="${h-7}">year</text>`;els.chart.innerHTML=svg;$('chartPercentile').textContent=`P${state.percentile}`}
function layerLabels(){return{pressure:['Δp · bar','Pressure change'],margin:['Remaining · bar','Pressure margin'],geothermal:['Cost impact · %','Geothermal injection impact'],co2:['Gas saturation · %','CO₂ plume saturation'],depth:['Top depth · m','Reservoir top depth'],thickness:['Thickness · m','Gross reservoir thickness'],permeability:['Permeability · mD','Permeability'],porosity:['Porosity · %','Porosity']}[state.layer]}
function renderLegend(){const[lo,hi]=ranges(),labels=layerLabels();$('legendLow').textContent=fmt(lo,state.layer==='porosity'?1:0);$('legendHigh').textContent=fmt(hi,state.layer==='porosity'?1:0);$('legendUnit').textContent=labels[0];$('legendRamp').style.background=`linear-gradient(90deg,${palettes[state.layer].join(',')})`;$('legendCaption').textContent=`P${state.percentile} · ${state.reservoir.is_opm_result?'OPM Flow ensemble':'analytical proxy'}`;$('mapTitle').textContent=`${labels[1]} · Year ${state.year}`}
function render(){if(!state.reservoir)return;$('rateOutput').textContent=`${state.rate.toFixed(1)} Mt/yr`;$('durationOutput').textContent=`${state.duration} yr`;$('yearOutput').textContent=`Year ${state.year}`;$('betaStatus').textContent=state.betaEnabled?'ACTIVE · 1.0 Mt/yr':'OFF';$('faultCaption').textContent={open:'Transmissibility multiplier 1.0',"semi-open":'Transmissibility multiplier 0.05',closed:'Transmissibility multiplier 0.0001'}[state.faultState];renderLegend();renderMap();renderDetail()}

els.reservoir.addEventListener('change',e=>selectReservoir(e.target.value));els.rate.addEventListener('input',e=>{state.rate=Number(e.target.value);render()});els.duration.addEventListener('input',e=>{state.duration=Number(e.target.value);render()});els.year.addEventListener('input',e=>{state.year=Number(e.target.value);render()});els.limit.addEventListener('change',e=>{state.limit=Math.max(1,Number(e.target.value));render()});document.querySelectorAll('.layer-button').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.layer-button').forEach(x=>x.classList.remove('active'));b.classList.add('active');state.layer=b.dataset.layer;render()}));document.querySelectorAll('.percentiles button').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.percentiles button').forEach(x=>x.classList.remove('active'));b.classList.add('active');state.percentile=Number(b.dataset.p);render()}));
$('basemapToggle').addEventListener('click',()=>{state.basemap=!state.basemap;$('basemapToggle').classList.toggle('active',state.basemap);$('basemapToggle').setAttribute('aria-pressed',String(state.basemap));$('basemapStatus').textContent=state.basemap?'Visible · roads and places':'Hidden';renderMap()});$('wellsToggle').addEventListener('click',()=>{state.showWells=!state.showWells;$('wellsToggle').classList.toggle('active',state.showWells);$('wellsToggle').setAttribute('aria-pressed',String(state.showWells));$('wellsStatus').textContent=state.showWells?`${state.context.legacy_wells.length} wells visible`:'Hidden';renderMap()});$('faultsToggle').addEventListener('click',()=>{state.showFaults=!state.showFaults;$('faultsToggle').classList.toggle('active',state.showFaults);$('faultsToggle').setAttribute('aria-pressed',String(state.showFaults));$('faultsStatus').textContent=state.showFaults?`${state.context.faults.length} supplied traces`:'Hidden';renderMap()});$('betaToggle').addEventListener('change',e=>{state.betaEnabled=e.target.checked;render()});$('faultState').addEventListener('change',e=>{state.faultState=e.target.value;render()});
$('evaluateButton').addEventListener('click',()=>{render();$('evaluateButton').textContent='Scenario evaluated';setTimeout(()=>$('evaluateButton').textContent='Evaluate scenario',1200)});$('fitButton').addEventListener('click',()=>{fitView();renderMap()});$('zoomIn').addEventListener('click',()=>zoomMap(1));$('zoomOut').addEventListener('click',()=>zoomMap(-1));$('aboutButton').addEventListener('click',()=>$('aboutDialog').showModal());$('searchInput').addEventListener('input',e=>{const q=e.target.value.toLowerCase();if(q.includes('north'))state.selectedIndex=Math.floor(state.reservoir.points.length*.7);else if(q.includes('south'))state.selectedIndex=Math.floor(state.reservoir.points.length*.3);else if(/^\d+$/.test(q))state.selectedIndex=Math.min(state.reservoir.points.length-1,Math.max(0,Number(q)-1));render()});
els.map.addEventListener('wheel',e=>{e.preventDefault();const r=els.map.getBoundingClientRect(),h=mapHeight();zoomMap(e.deltaY<0?1:-1,{x:(e.clientX-r.left)/r.width*MAP_W,y:(e.clientY-r.top)/r.height*h})},{passive:false});els.map.addEventListener('pointerdown',e=>{els.map.setPointerCapture(e.pointerId);mapDrag={x:e.clientX,y:e.clientY,centre:world(state.view)};mapMoved=false});els.map.addEventListener('pointermove',e=>{if(!mapDrag)return;const r=els.map.getBoundingClientRect(),dx=(e.clientX-mapDrag.x)/r.width*MAP_W,dy=(e.clientY-mapDrag.y)/r.height*mapHeight();if(Math.abs(dx)+Math.abs(dy)>4)mapMoved=true;state.view={...unworld(mapDrag.centre.x-dx,mapDrag.centre.y-dy),zoom:state.view.zoom};renderMap()});els.map.addEventListener('pointerup',e=>{mapDrag=null;if(!mapMoved&&e.target.classList.contains('model-cell')){state.selectedIndex=Number(e.target.dataset.index);render()}setTimeout(()=>mapMoved=false,0)});window.addEventListener('resize',()=>state.reservoir&&renderMap());

Promise.all([fetch('data/pressure-model.json?v=0.3.1',{cache:'no-store'}).then(r=>r.ok?r.json():Promise.reject(new Error('Pressure dataset failed to load'))),fetch('data/regional-context.json?v=0.3.1',{cache:'no-store'}).then(r=>r.ok?r.json():Promise.reject(new Error('Regional context failed to load')))]).then(([model,context])=>{state.model=model;state.context=context;$('wellsStatus').textContent=`${context.legacy_wells.length} wells visible`;$('faultsStatus').textContent=`${context.faults.length} supplied traces`;populateReservoirs()}).catch(error=>{$('engineLabel').textContent='Model unavailable';document.querySelector('.map-canvas').innerHTML=`<p style="padding:2rem;color:#d98b76">${error.message}</p>`});
